// Original cut-paper illustration; geometric paths describe anatomy, not placeholder markers.
export function drawInkfin(c,g,{reduced=false,effects='full'}={}){const ctx=c.getContext('2d'),dpr=Math.min(2,globalThis.devicePixelRatio||1),w=Math.max(1,c.clientWidth),h=Math.max(1,c.clientHeight);if(c.width!==Math.round(w*dpr)||c.height!==Math.round(h*dpr)){c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);}ctx.setTransform(c.width/1000,0,0,c.height/560,0,0);const t=g.clock,gradient=ctx.createLinearGradient(0,0,0,560);gradient.addColorStop(0,'#112d43');gradient.addColorStop(.6,'#174b58');gradient.addColorStop(1,'#193b4a');ctx.fillStyle=gradient;ctx.fillRect(0,0,1000,560);
 function path(d,fill,stroke=null,width=2){const p=new Path2D(d);ctx.fillStyle=fill;ctx.fill(p);if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke(p);}}
 ctx.save();ctx.globalAlpha=.13;for(let i=0;i<8;i++){ctx.fillStyle=i%2?'#a6d9c8':'#93b4d6';ctx.beginPath();ctx.moveTo(i*165-100,0);ctx.lineTo(i*165+30,0);ctx.lineTo(i*165+200,560);ctx.lineTo(i*165-30,560);ctx.fill();}ctx.restore();
 for(let layer=0;layer<2;layer++){ctx.save();ctx.globalAlpha=layer?.65:.35;for(let i=0;i<17;i++){ctx.save();ctx.translate(i*67+Math.sin(i)*14,560);ctx.rotate(Math.sin(t*.5+i)*.025*(reduced?0:1));const height=50+(i*41%130);path(`M0 0C-18-${height/2} 25-${height} 5-${height+30}C40-${height} 8-${height/2} 20 0Z`,layer?'#357b75':'#2c6169');for(let j=0;j<4;j++)path(`M8-${j*height/4}q-48-28-27-52q42 5 35 52`,layer?'#4c9783':'#315e6c');ctx.restore();}ctx.restore();}
 for(const rock of g.rocks){ctx.save();ctx.translate(rock.x,rock.y);ctx.scale(rock.r/65,rock.r/65);path('M-63 14Q-75-35-25-54Q12-76 51-34Q84-3 55 47Q2 76-49 48Z','#426b75','#719390',3);path('M-48-8Q-17-54 21-38L48-3Q10-21-7 13Z','#6d908d');path('M-42 34Q-18 17 8 34T50 30L33 51-20 57Z','#274e60');for(let i=0;i<5;i++){ctx.save();ctx.translate(-40+i*19,42);path('M0 0Q-14-35-8-58Q9-55 8-31Q24-51 30-40Q31-25 12-13L12 0Z',i%2?'#c486a4':'#caa483','#e6c49c88',1.5);ctx.restore();}ctx.restore();}
 const home=g.home;ctx.save();ctx.translate(home.x,home.y);ctx.shadowColor='#b3e9c0';ctx.shadowBlur=20;path('M-59 70L-59-20Q-58-90 0-92Q58-90 59-20L59 70Z','#386f77','#a6cbb0',4);ctx.shadowBlur=0;path('M-42 65V-19Q-40-69 0-72Q40-69 42-19V65Z','#173c50','#d5cb91',3);for(let i=0;i<5;i++){ctx.strokeStyle='#9bc5ae77';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-42,-15+i*17);ctx.quadraticCurveTo(0,-35+i*18,42,-15+i*17);ctx.stroke();}ctx.fillStyle='#e5dbaf';ctx.font='bold 16px Outfit,sans-serif';ctx.textAlign='center';ctx.fillText('SANCTUARY',0,98);ctx.font='20px Outfit,sans-serif';ctx.fillText(g.saved+'/8',0,8);ctx.restore();
 for(const v of g.vents){ctx.save();ctx.translate(v.x,v.y);path('M-24 18L-19-5Q0-29 19-5L24 18Z','#c2ac88','#e5d0a1');for(let i=0;i<5;i++){const y=((t*24+i*16)%85);ctx.strokeStyle='#a8e5dc66';ctx.beginPath();ctx.arc(Math.sin(i+t)*11,-y,3+i%3,0,Math.PI*2);ctx.stroke();}ctx.restore();}
 for(let i=0;i<Math.ceil(g.level/2);i++){const j=g.jelly(i);ctx.save();ctx.translate(j.x,j.y);ctx.globalAlpha=.83;for(let n=-2;n<=2;n++){ctx.strokeStyle='#e1a0bc';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(n*8,6);ctx.bezierCurveTo(n*10+Math.sin(t*2+n)*9,22,n*12-8,42,n*10+Math.sin(t*2+n)*14,57);ctx.stroke();}path('M-25 5Q-30-35 0-38Q30-35 25 5Q12 18 0 6Q-12 18-25 5Z','#a87ba9','#e1b6d1',2);path('M-13-14Q-4-29 8-23L16-9Q1-17-13-14Z','#dfb8cb');ctx.restore();}
 for(const f of g.fish){if(f.rescued)continue;ctx.save();ctx.translate(f.x,f.y);ctx.rotate(Math.atan2(f.vy,f.vx||1));ctx.scale(.85,.85);const wiggle=Math.sin(t*9+f.id)*(reduced?.1:1),color=['#f0c78a','#b5d9c5','#c3afda'][f.id%3];path(`M-17 0Q-38-${15+wiggle*3}-37-14Q-34 0-37 17Q-23 12-17 0Z`,color,'#183f51',2);path('M-19 0Q-7-20 12-11Q31-4 26 2Q15 17-3 13Q-16 10-19 0Z',color,'#24495a',2);path('M-3-13Q2-28 12-16L14-10Z','#da9ca6','#3f5c68',1);path('M0 7Q-3 22 10 19L15 9Z','#a87da4');for(let n=0;n<3;n++){ctx.strokeStyle='#556d7b77';ctx.beginPath();ctx.arc(-7+n*8,0,5,-1.2,1.2);ctx.stroke();}ctx.fillStyle='#f4ead5';ctx.beginPath();ctx.arc(17,-4,4,0,7);ctx.fill();ctx.fillStyle='#1a3448';ctx.beginPath();ctx.arc(18,-4,2,0,7);ctx.fill();if(f.stun){ctx.strokeStyle='#e6b0cc';ctx.beginPath();ctx.arc(0,0,29,0,7);ctx.stroke();}ctx.restore();}
 for(let i=0;i<(effects==='off'?0:effects==='reduced'||reduced?10:35);i++){const x=(i*137.3)%1000,y=560-((t*(7+i%4)+i*73)%590);ctx.strokeStyle='#a9d8cf22';ctx.beginPath();ctx.arc(x,y,1+i%3,0,7);ctx.stroke();}
 for(const [i,l]of g.lures.entries()){if(!l.active)continue;ctx.save();ctx.translate(l.x,l.y);ctx.strokeStyle=i?'#f3c391':'#a4e1d6';ctx.lineWidth=3;ctx.setLineDash(l.repel?[6,5]:[]);ctx.beginPath();ctx.arc(0,0,25+Math.sin(t*4)*3,0,7);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=.18;ctx.beginPath();ctx.arc(0,0,85,0,7);ctx.stroke();ctx.globalAlpha=1;ctx.font='bold 16px Outfit,sans-serif';ctx.fillStyle=ctx.strokeStyle;ctx.textAlign='center';ctx.fillText('P'+(i+1)+(l.repel?' PUSH':' CALL'),0,-38);ctx.restore();}
}
